     <title>Terms Consent Form</title>
     <style>
       :root {
         color-scheme: dark;
         font-family:
           Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
           "Segoe UI", sans-serif;
         background: #080b12;
         color: #f7fafc;
       }

       * {
         box-sizing: border-box;
       }

       body {
         min-height: 100vh;
         margin: 0;
         display: grid;
         place-items: center;
         padding: 32px 16px;
         background:
           radial-gradient(circle at top left, rgba(99, 102, 241, 0.28), transparent 34rem),
           radial-gradient(circle at bottom right, rgba(20, 184, 166, 0.2), transparent 30rem),
           #080b12;
       }

       .app-shell {
         width: min(100%, 440px);
       }

       .consent-card {
         border: 1px solid rgba(148, 163, 184, 0.18);
         border-radius: 28px;
         padding: 32px;
         background: rgba(15, 23, 42, 0.82);
         box-shadow: 0 24px 80px rgba(0, 0, 0, 0.42);
         backdrop-filter: blur(18px);
       }

       .eyebrow {
         margin: 0 0 10px;
         color: #5eead4;
         font-size: 0.78rem;
         font-weight: 700;
         letter-spacing: 0.14em;
         text-transform: uppercase;
       }

       h1 {
         margin: 0;
         font-size: clamp(2rem, 8vw, 3rem);
         line-height: 1;
         letter-spacing: -0.06em;
       }

       .intro {
         margin: 16px 0 28px;
         color: #cbd5e1;
         line-height: 1.6;
       }

       .form-field {
         display: grid;
         grid-template-columns: auto 1fr;
         gap: 12px 14px;
         align-items: start;
         padding: 18px;
         border: 1px solid rgba(148, 163, 184, 0.2);
         border-radius: 18px;
         background: rgba(2, 6, 23, 0.5);
       }

       .form-field input[type="checkbox"] {
         width: 22px;
         height: 22px;
         margin: 2px 0 0;
         accent-color: #5eead4;
         cursor: pointer;
       }

       .checkbox-copy {
         display: grid;
         gap: 6px;
       }

       label {
         color: #f8fafc;
         font-weight: 700;
         line-height: 1.35;
         cursor: pointer;
       }

       .helper-text {
         margin: 0;
         color: #94a3b8;
         font-size: 0.92rem;
         line-height: 1.5;
       }

       button {
         width: 100%;
         margin-top: 20px;
         border: 0;
         border-radius: 16px;
         padding: 15px 18px;
         color: #03110f;
         background: linear-gradient(135deg, #5eead4, #a7f3d0);
         box-shadow: 0 14px 30px rgba(45, 212, 191, 0.2);
         font: inherit;
         font-weight: 800;
         cursor: pointer;
         transition:
           transform 160ms ease,
           box-shadow 160ms ease;
       }

       button:hover {
         transform: translateY(-1px);
         box-shadow: 0 18px 38px rgba(45, 212, 191, 0.26);
       }

       button:focus-visible,
       input:focus-visible {
         outline: 3px solid rgba(94, 234, 212, 0.45);
         outline-offset: 3px;
       }

       .status {
         min-height: 1.4em;
         margin: 16px 0 0;
         color: #a7f3d0;
         font-weight: 700;
         text-align: center;
       }
     </style>
   </head>
   <body>
     <main id="root" class="app-shell"></main>

     <script>
       function FormField() {
         return `
           <div class="form-field">
             <input id="terms" name="terms" type="checkbox" required>
             <div class="checkbox-copy">
               <label for="terms">I agree to the terms of use</label>
               <p class="helper-text">Required to continue with your submission.</p>
             </div>
           </div>
         `;
       }

       function ConsentForm() {
         return `
           <section class="consent-card" aria-labelledby="form-title">
             <p class="eyebrow">Consent required</p>
             <h1 id="form-title">Terms agreement</h1>
             <p class="intro">
               Confirm your acceptance before sending the form.
             </p>
             <form id="consent-form">
               ${FormField()}
               <button type="submit">Submit</button>
               <p id="status" class="status" role="status" aria-live="polite"></p>
             </form>
           </section>
         `;
       }

       function App() {
         return ConsentForm();
       }

       document.querySelector("#root").innerHTML = App();

       document.querySelector("#consent-form").addEventListener("submit", (event) => {
         event.preventDefault();
         document.querySelector("#status").textContent = "Thanks, your consent was recorded.";
       });
     </script>
   </body>
 </html>

')
